import{_ as n,a0 as r,w as l,s as h,ao as p,I as i,x as t,a1 as o,A as a}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const _=JSON.parse('{"title":"如何實現ssh無密碼登錄 | LCTT x X-CMD","titleTemplate":false,"description":"如何實現ssh無密碼登錄 | LCTT (201505) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何實現ssh無密碼登錄 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何實現ssh無密碼登錄 | LCTT (201505) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201505/20150323 How to enable ssh login without entering password","title":"如何實現ssh無密碼登錄","tag":"201505","desc":""},"relativePath":"201505/20150323 How to enable ssh login without entering password.md","filePath":"[post].md"}'),d={name:"201505/20150323 How to enable ssh login without entering password.md"};function u(m,s,f,T,g,w){const e=r("Link");return l(),h("div",null,[s[13]||(s[13]=p(`<h1 id="如何實現ssh無密碼登錄" tabindex="-1">如何實現ssh無密碼登錄 <a class="header-anchor" href="#如何實現ssh無密碼登錄" aria-label="Permalink to “如何實現ssh無密碼登錄”">​</a></h1><p>假設你是hostA上的一個用户&quot;aliceA&quot;，想以用户“aliceB”的身份ssh到hostB上，但又不想輸入密碼。那麼，你可以參考這篇教程實現ssd無密碼登錄。</p><p>首先，你需要以用户“aliceA”的身份登錄到hostA上。</p><p>然後，使用ssh-keygen生成一對rsa公私鑰，生成的密鑰對會存放在~/.ssh目錄下。</p><pre><code>$ ssh-keygen -t rsa
</code></pre><p>接下來，使用下面的命令在目標主機hostB上的aliceB用户目錄下創建~/.ssh目錄。如果在aliceB@hostB上已經存在.ssh目錄，這一步會被略過。</p><pre><code>$ ssh aliceB@hostB mkdir -p .ssh
</code></pre><p>最後，將hostA上用户“aliceA”的公鑰拷貝到aliceB@hostB上，來實現無密碼ssh。</p><pre><code>$ cat .ssh/id_rsa.pub | ssh aliceB@hostB &#39;cat &gt;&gt; .ssh/authorized_keys&#39;
</code></pre><p>自此以後，從aliceA@hostA上ssh到aliceB@hostB上再也不需要輸入密碼。（LCTT 譯註：上述的創建目錄並複製的操作也可以通過一個 ssh-copy-id 命令一步完成：<code>ssh-copy-id -i ~/.ssh/id_rsa.pub aliceB@hostB</code>）</p><h3 id="疑難解答" tabindex="-1">疑難解答 <a class="header-anchor" href="#疑難解答" aria-label="Permalink to “疑難解答”">​</a></h3><ol><li><p>即使在密鑰認證生效後，你可能仍然需要輸入SSH密碼。如果遇到這種情況，請檢查系統日誌（如/var/log/secure）以查看是否出現下面的異常。</p><p>Authentication refused: bad ownership or modes for file /home/aliceB/.ssh/authorized_keys</p></li></ol><p>在這種情況下，密鑰認證的失敗是由於~/.ssh/authorized_keys文件的權限或擁有者不正確。一般情況，如果這個文件對除了你之外的所有用户都可讀，就會出現這個錯誤。用下面的方式改變文件的權限以修正錯誤。</p><pre><code>$ chmod 700 ~/.ssh/authorized_keys 
</code></pre><hr>`,15)),i("p",null,[s[1]||(s[1]=t("via: ",-1)),o(e,{href:"http://xmodulo.com/how-to-enable-ssh-login-without.html"},{default:a(()=>[...s[0]||(s[0]=[t("http://xmodulo.com/how-to-enable-ssh-login-without.html",-1)])]),_:1})]),i("p",null,[s[5]||(s[5]=t("作者：",-1)),o(e,{href:"http://xmodulo.com/author/nanni"},{default:a(()=>[...s[2]||(s[2]=[t("Dan Nanni",-1)])]),_:1}),s[6]||(s[6]=t(" 譯者：",-1)),o(e,{href:"https://github.com/KayGuoWhu"},{default:a(()=>[...s[3]||(s[3]=[t("KayGuoWhu",-1)])]),_:1}),s[7]||(s[7]=t(" 校對：",-1)),o(e,{href:"https://github.com/wxy"},{default:a(()=>[...s[4]||(s[4]=[t("wxy",-1)])]),_:1})]),i("p",null,[s[10]||(s[10]=t("本文由 ",-1)),o(e,{href:"https://github.com/LCTT/TranslateProject"},{default:a(()=>[...s[8]||(s[8]=[t("LCTT",-1)])]),_:1}),s[11]||(s[11]=t(" 原創翻譯，",-1)),o(e,{href:"http://linux.cn/"},{default:a(()=>[...s[9]||(s[9]=[t("Linux中國",-1)])]),_:1}),s[12]||(s[12]=t(" 榮譽推出",-1))])])}const C=n(d,[["render",u]]);export{_ as __pageData,C as default};
